CREATE OR REPLACE FUNCTION public.derive_org_product_zalo_server_flag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_package_is_zalo_server boolean;
BEGIN
  SELECT COALESCE(package.is_zalo_server, false)
  INTO v_package_is_zalo_server
  FROM public.org_product_package AS package
  WHERE package.id = NEW.product_package_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization_product_package_not_found';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.is_zalo_server :=
      COALESCE(NEW.is_zalo_server, false)
      OR v_package_is_zalo_server;
  ELSE
    NEW.is_zalo_server :=
      COALESCE(OLD.is_zalo_server, false)
      OR COALESCE(NEW.is_zalo_server, false)
      OR v_package_is_zalo_server;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_zalo_chat_referral_ai_log_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_old_reserved boolean := false;
  v_new_reserved boolean := false;
begin
  if tg_op in ('INSERT', 'UPDATE') then
    v_new_reserved := coalesce(new.using_code, '') = 'zalo_chat_referral_verify_v1'
      or coalesce(new.block_name, '') = 'zalo-chat-referral-precreate-v1';
  end if;
  if tg_op in ('UPDATE', 'DELETE') then
    v_old_reserved := coalesce(old.using_code, '') = 'zalo_chat_referral_verify_v1'
      or coalesce(old.block_name, '') = 'zalo-chat-referral-precreate-v1';
  end if;

  if current_user not in ('postgres', 'service_role') and (v_old_reserved or v_new_reserved) then
    raise exception using errcode = '42501', message = 'zalo_referral_ai_log_backend_only';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.serialize_zalo_runtime_entitlement_change()
