CREATE OR REPLACE FUNCTION public.aka_agent_call_email_notification_worker(p_mode text DEFAULT 'process'::text, p_reason text DEFAULT 'manual'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'net'
AS $function$
DECLARE
  v_url text := public.aka_agent_get_vault_secret('AKA_AGENT_EMAIL_NOTIFICATION_WORKER_URL');
  v_token text := public.aka_agent_get_vault_secret('INTERNAL_EDGE_FUNCTION_TOKEN');
  v_request_id bigint;
BEGIN
  IF v_url IS NULL OR btrim(v_url) = '' OR v_token IS NULL OR btrim(v_token) = '' THEN
    RAISE NOTICE 'Email notification worker URL/token is not configured in Supabase Vault.';
    RETURN NULL;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN
    RAISE NOTICE 'pg_net extension is not installed; email notification worker was not invoked.';
    RETURN NULL;
  END IF;

  SELECT net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-internal-token', v_token
    ),
    body := jsonb_build_object(
      'mode', COALESCE(NULLIF(p_mode, ''), 'process'),
      'reason', COALESCE(NULLIF(p_reason, ''), 'manual')
    )
  )
  INTO v_request_id;

  RETURN v_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_dataset_auto_group_key(p_source text, p_account_id bigint, p_flatform_type text, p_contact_type text, p_scan_type text, p_source_key text, p_data_type_category_item_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_source_key text := btrim(COALESCE(p_source_key, ''));
  v_upload_source_key text;
  v_identity jsonb;
BEGIN
  IF p_source = 'upload' AND p_account_id IS NOT NULL THEN
    v_upload_source_key := regexp_replace(
      v_source_key,
      ':' || p_account_id::text || '$',
      ''
    );
    v_identity := jsonb_build_object(
      'source', 'upload',
      'platform', COALESCE(p_flatform_type, ''),
      'contactType', COALESCE(p_contact_type, ''),
      'scanType', COALESCE(p_scan_type, ''),
      'sourceKey', v_upload_source_key,
      'dataTypeCategoryItemId', p_data_type_category_item_id
    );
  ELSE
    v_identity := jsonb_build_object(
      'source', COALESCE(p_source, ''),
      'accountId', p_account_id,
      'platform', COALESCE(p_flatform_type, ''),
      'contactType', COALESCE(p_contact_type, ''),
      'scanType', COALESCE(p_scan_type, ''),
      'sourceKey', v_source_key,
      'dataTypeCategoryItemId', p_data_type_category_item_id
    );
  END IF;

  RETURN COALESCE(p_source, 'dataset') || ':' || md5(v_identity::text);
END;
$function$
